def compute(vars):
    shares_per_holder = vars["v1"] / vars["v2"] if vars["v2"] != 0 else None
    return {
        "value": shares_per_holder,
        "trace": {
            "shares": vars["v1"],
            "registered_holders": vars["v2"],
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "shares per registered holder"
            }
        }
    }
